/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Tests
 *   - the guard refuses and records fetch, DNS, resolvers, sockets, HTTPS and the default pinned fetcher, and restores the originals
 *   - the guard also refuses module-level promise resolvers, reverse lookups, lookupService and URL or Request fetches
 *   - an IPC connection is not a network attempt
 *   - a loopback fetch passes through the guard while a non-loopback fetch is refused
 *   - a loopback server round-trip still works under the guard
 * @end-catalog */

import assert from 'node:assert/strict';
import dns from 'node:dns';
import http from 'node:http';
import https from 'node:https';
import net from 'node:net';
import { once } from 'node:events';
import { test } from 'node:test';
import { openPinnedHttps, strictHttpsUrl } from '../../src/administration/adminPinnedHttps';
import { NetworkGuardError, installNetworkGuard } from '../support/networkGuard';

test('the guard refuses and records fetch, DNS, resolvers, sockets, HTTPS and the default pinned fetcher, and restores the originals', async () => {
    const originals = {
        fetch: globalThis.fetch, connect: net.Socket.prototype.connect, lookup: dns.lookup, promiseLookup: dns.promises.lookup,
        resolve4: dns.Resolver.prototype.resolve4, promiseResolve4: dns.promises.Resolver.prototype.resolve4, moduleResolve4: dns.resolve4
    };
    const guard = installNetworkGuard();
    try {
        await assert.rejects(fetch('https://musicbrainz.org/ws/2/release'), NetworkGuardError);
        await assert.rejects(dns.promises.lookup('musicbrainz.org'), NetworkGuardError);
        await assert.rejects(new dns.promises.Resolver().resolve4('musicbrainz.org'), NetworkGuardError);
        await new Promise<void>(resolve => dns.resolve4('itunes.apple.com', error => { assert.ok(error instanceof NetworkGuardError); resolve(); }));
        await new Promise<void>(resolve => new dns.Resolver().resolve6('coverartarchive.org', error => { assert.ok(error instanceof NetworkGuardError); resolve(); }));
        await new Promise<void>(resolve => dns.lookup('archive.org', error => { assert.ok(error instanceof NetworkGuardError); resolve(); }));
        const outgoing = https.request({ host: '198.51.100.7', port: 443, path: '/', method: 'GET' });
        const [error] = await once(outgoing, 'error');
        assert.ok(error instanceof NetworkGuardError);
        await assert.rejects(openPinnedHttps(new URL('https://musicbrainz.org/ws/2/release'), AbortSignal.timeout(5000), {
            destination: url => strictHttpsUrl(url.href), headers: { Accept: 'application/json', 'User-Agent': 'guard-test' },
            maximumRedirects: 0, failure: () => new Error('PINNED_REFUSED')
        }), /PINNED_REFUSED/);
        assert.deepEqual(guard.attempts.slice(0, 7), ['fetch:musicbrainz.org', 'lookup:musicbrainz.org', 'resolve4:musicbrainz.org',
            'resolve4:itunes.apple.com', 'resolve6:coverartarchive.org', 'lookup:archive.org', 'connect:198.51.100.7']);
        assert.ok(guard.attempts.slice(7).some(attempt => attempt.endsWith(':musicbrainz.org')), 'the default pinned fetcher resolves through the guarded resolver');
    } finally { guard.restore(); }
    assert.equal(globalThis.fetch, originals.fetch); assert.equal(net.Socket.prototype.connect, originals.connect);
    assert.equal(dns.lookup, originals.lookup); assert.equal(dns.promises.lookup, originals.promiseLookup);
    assert.equal(dns.Resolver.prototype.resolve4, originals.resolve4); assert.equal(dns.promises.Resolver.prototype.resolve4, originals.promiseResolve4);
    assert.equal(dns.resolve4, originals.moduleResolve4);
});

test('the guard also refuses module-level promise resolvers, reverse lookups, lookupService and URL or Request fetches', async () => {
    const originals = { resolve4: dns.promises.resolve4, reverse: dns.reverse, lookupService: dns.promises.lookupService };
    const guard = installNetworkGuard();
    try {
        await assert.rejects(dns.promises.resolve4('musicbrainz.org'), NetworkGuardError);
        await assert.rejects(dns.promises.resolveTxt('itunes.apple.com'), NetworkGuardError);
        await assert.rejects(dns.promises.reverse('8.8.8.8'), NetworkGuardError);
        await assert.rejects(dns.promises.lookupService('8.8.8.8', 443), NetworkGuardError);
        await new Promise<void>(resolve => dns.reverse('8.8.4.4', error => { assert.ok(error instanceof NetworkGuardError); resolve(); }));
        await assert.rejects(fetch(new URL('https://coverartarchive.org/release/x')), NetworkGuardError);
        await assert.rejects(fetch(new Request('https://archive.org/download/x')), NetworkGuardError);
        assert.deepEqual(guard.attempts, ['resolve4:musicbrainz.org', 'resolveTxt:itunes.apple.com', 'reverse:8.8.8.8', 'lookupService:8.8.8.8',
            'reverse:8.8.4.4', 'fetch:coverartarchive.org', 'fetch:archive.org']);
    } finally { guard.restore(); }
    assert.deepEqual({ resolve4: dns.promises.resolve4, reverse: dns.reverse, lookupService: dns.promises.lookupService }, originals);
});

test('an IPC connection is not a network attempt', async () => {
    const guard = installNetworkGuard();
    const pipe = process.platform === 'win32' ? `\\\\.\\pipe\\archtree-network-guard-${process.pid}` : `/tmp/archtree-network-guard-${process.pid}.sock`;
    const server = net.createServer(socket => socket.end('ipc'));
    try {
        server.listen(pipe); await once(server, 'listening');
        const reply = await new Promise<string>((resolve, reject) => {
            const socket = net.connect(pipe);
            let data = '';
            socket.on('data', chunk => { data += chunk; }).on('end', () => resolve(data)).on('error', reject);
        });
        assert.equal(reply, 'ipc'); assert.deepEqual(guard.attempts, []);
    } finally { server.close(); guard.restore(); }
});

test('a loopback fetch passes through the guard while a non-loopback fetch is refused', async () => {
    const guard = installNetworkGuard();
    const server = http.createServer((_request, response) => response.end('loopback'));
    try {
        server.listen(0, '127.0.0.1'); await once(server, 'listening');
        const { port } = server.address() as net.AddressInfo;
        assert.equal(await (await fetch(`http://127.0.0.1:${port}/`)).text(), 'loopback');
        assert.equal(await (await fetch(new URL(`http://localhost:${port}/`))).text(), 'loopback');
        await assert.rejects(fetch('https://musicbrainz.org/ws/2/release'), NetworkGuardError);
        assert.deepEqual(guard.attempts, ['fetch:musicbrainz.org']);
    } finally { server.closeAllConnections(); server.close(); guard.restore(); }
});

test('a loopback server round-trip still works under the guard', async () => {
    const guard = installNetworkGuard();
    const server = net.createServer(socket => socket.end('pong'));
    try {
        server.listen(0, '127.0.0.1'); await once(server, 'listening');
        const { port } = server.address() as net.AddressInfo;
        const reply = await new Promise<string>((resolve, reject) => {
            const socket = net.connect(port, '127.0.0.1');
            let data = '';
            socket.on('data', chunk => { data += chunk; }).on('end', () => resolve(data)).on('error', reject);
        });
        assert.equal(reply, 'pong');
        const local = await new Promise<string>((resolve, reject) => {
            const socket = net.connect({ port, host: 'localhost' });
            let data = '';
            socket.on('data', chunk => { data += chunk; }).on('end', () => resolve(data)).on('error', reject);
        });
        assert.equal(local, 'pong');
        assert.deepEqual(guard.attempts, []);
    } finally { server.close(); guard.restore(); }
});
